CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY, slug TEXT UNIQUE NOT NULL, name TEXT NOT NULL, blurb TEXT, sort INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS ingredients(id INTEGER PRIMARY KEY, slug TEXT UNIQUE NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL, color TEXT, info TEXT);
CREATE TABLE IF NOT EXISTS items(id INTEGER PRIMARY KEY, slug TEXT UNIQUE NOT NULL, category_id INTEGER NOT NULL REFERENCES categories(id), name TEXT NOT NULL, price INTEGER, description TEXT, badge TEXT, available INTEGER DEFAULT 1, builder TEXT NOT NULL, params TEXT NOT NULL, sort INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS item_ingredients(item_id INTEGER NOT NULL REFERENCES items(id) ON DELETE CASCADE, ingredient_id INTEGER NOT NULL REFERENCES ingredients(id), position INTEGER NOT NULL, role TEXT, PRIMARY KEY(item_id, position));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY, created TEXT NOT NULL, name TEXT NOT NULL, phone TEXT NOT NULL, address TEXT NOT NULL, notes TEXT, total INTEGER, status TEXT DEFAULT 'received');
CREATE TABLE IF NOT EXISTS order_items(order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, item_slug TEXT NOT NULL, name TEXT NOT NULL, qty INTEGER NOT NULL, price INTEGER);
